<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\SoftDeletes; class Product extends Model {use SoftDeletes; protected $fillable=['photo','barcode','qr_code','code','sku','name','category','brand','supplier_id','warehouse_id','rack_location','unit','cost_price','selling_price','minimum_stock','current_stock','status','notes']; protected $casts=['cost_price'=>'decimal:2','selling_price'=>'decimal:2']; public function supplier(){return $this->belongsTo(Supplier::class);} public function warehouse(){return $this->belongsTo(Warehouse::class);} public function histories(){return $this->hasMany(StockHistory::class);}}
